/* @socom-skeleton body GetMesh__Q23zdb5CNodeFv */
zdb::CMesh * zdb::CNode::GetMesh()
	{
		/* 0x229510: the first visual when it is a CMesh (vtype 1), else NULL. (The earlier
		   port tested a legacy m_has_lods flag nothing set, so hookupVisuals never reached
		   hookupMesh and every mesh model kept a NULL LOD 0 chain.) */
		CVisual* mesh = NULL;

		if (m_visual.size() != 0)
			mesh = m_visual[0];

		if (mesh != NULL && mesh->m_vtype == 1)
			return static_cast<CMesh*>(mesh);

		return NULL;
	}

/* @socom-skeleton stub GetSubMesh__Q23zdb5CNodeFv */
zdb::CSubMesh * zdb::CNode::GetSubMesh()
{
	/* 0x229490: the first visual when it is a CSubMesh (vtype 2; __dynamic_cast from
	   CVisual), else NULL */
	CVisual* visual = NULL;

	if (m_visual.size() != 0)
		visual = m_visual[0];

	if (visual == NULL || visual->m_vtype != 2)
		return NULL;

	return dynamic_cast<CSubMesh*>(visual);
}

/* @socom-skeleton stub GetFirstVisual__Q23zdb5CNodeFv */
zdb::CVisual * zdb::CNode::GetFirstVisual()
{
	/* 0x229460: the first entry of m_visual, or NULL when it is empty */
	if (m_visual.size() == 0)
		return NULL;

	return m_visual[0];
}

/* @socom-skeleton body CreateInstance__Q23zdb5CNodeFPQ23zdb6CModelPC6CPnt3DPC5CQuat */
namespace zdb {
CNode* CNode::CreateInstance(CModel* model, const CPnt3D* position, const CQuat* rotation)
	{
		if (!model)
			return NULL;

		CNode* instance = model->Copy();

		if (position)
			instance->SetPosition(position->x, position->y, position->z);

		if (rotation)
			instance->SetRotation(rotation);

		/* 0x2293d4: the model lists the instance (CModel::m_list, not its children); its
		 * m_parent is the instance only while that is the single one */
		model->m_list.insert(model->m_list.end(), instance);
		model->m_parent = model->m_list.size() == 1 ? instance : NULL;
		instance->m_model = model;
		instance->SetModelname(model->m_name);
		instance->m_type = (u32)TYPE::INSTANCE;

		return instance;
	}
}

/* @socom-skeleton body CreateInstance__Q23zdb5CNodeFPCcPC6CPnt3DPC5CQuat */
namespace zdb {
CNode* CNode::CreateInstance(const char* name, const CPnt3D* position, const CQuat* rotation)
	{
		if (!name)
			return NULL;

		if (!CWorld::m_world)
			return NULL;

		CModel* model = CWorld::GetModel(name);

		if (!model)
			return NULL;

		CNode* instance = model->Copy();

		if (position)
			instance->SetPosition(position->x, position->y, position->z);

		if (rotation)
			instance->SetRotation(rotation);

		/* 0x2293d4: the model lists the instance (CModel::m_list, not its children); its
		 * m_parent is the instance only while that is the single one */
		model->m_list.insert(model->m_list.end(), instance);
		model->m_parent = model->m_list.size() == 1 ? instance : NULL;
		instance->m_model = model;
		instance->SetModelname(model->m_name);
		instance->m_type = (u32)TYPE::INSTANCE;

		return instance;
	}
}

/* @socom-skeleton body CreateXRef__Q23zdb5CNodeFPQ23zdb6CModelPC6CPnt3DPC5CQuat */
namespace zdb {
CNode* CNode::CreateXRef(CModel* model, const CPnt3D* position, const CQuat* rotation)
	{
		if (!model)
			return NULL;

		CNode* xref = new CNode();

		if (position)
			xref->SetPosition(position->x, position->y, position->z);

		if (rotation)
			xref->SetRotation(rotation);

		xref->m_type = static_cast<u32>(TYPE::CHILD);
		xref->SetName("XRef");
		xref->AddChild(model);
	}
}

/* @socom-skeleton body CreateXRef__Q23zdb5CNodeFv */
namespace zdb {
CNode* CNode::CreateXRef()
	{
		CNode* xref = new CNode();
		xref->m_type = static_cast<u32>(TYPE::CHILD);
		xref->SetName("XRef");
		return xref;
	}
}

/* @socom-skeleton body Delete__Q23zdb5CNodeFPQ23zdb5CNode */
zdb::CNode * zdb::CNode::Delete(zdb::CNode *node)
	{
		/* 0x228fd0 (static): a type-4 node hands its first child to its parent; an
		   instance (type 2) leaves its model; both leave their parent; then the node is
		   deleted. The ELF switches on the low half of m_type and returns 0. */
		if (!node)
			return NULL;

		switch ((u16)node->m_type)
		{
		case (u16)TYPE::MULTI_PARENT:
		{
			CNode* parent = node->m_parent;
			CNode* child = node->m_child.size() != 0 ? node->m_child.front() : NULL;
			node->RemoveFromParent();

			if (child != NULL)
				child->RemoveFromParent();

			if (parent != NULL)
				parent->AddChild(child);

			break;
		}
		case (u16)TYPE::INSTANCE:
		{
			CModel* model = node->m_model;

			if (model != NULL)
				model->Release(node);

			node->RemoveFromParent();
			break;
		}
		}

		delete node;
		return NULL;
	}

/* @socom-skeleton body SetModel__Q23zdb5CNodeFPQ23zdb6CModel */
namespace zdb {
bool CNode::SetModel(CModel* model)
	{
		/* 0x228f20: only CHILD and INSTANCE nodes take a model; a CHILD node drops its
		 * children and holds the model as its child */
		if (m_type != (u32)TYPE::CHILD && m_type != (u32)TYPE::INSTANCE)
			return false;

		if (m_type == (u32)TYPE::CHILD)
		{
			DeleteChildren();
			if (model != NULL)
				AddChild(model);
		}

		m_model = model;
		SetModelname(model != NULL ? model->m_name : NULL);
		return true;
	}
}